//! OpenFlow 1.3 controller server (passive mode)
//!
//! Listens for OVS to connect (passive mode), performs the OF1.3 handshake,
//! discovers port numbers by name via a PortDesc multipart request, clears all
//! existing flows, and installs the configured forwarding rules.
//!
//! Wire-protocol encoding is delegated to `rovs_openflow` types wherever
//! possible; the TCP listener and passive handshake are implemented here
//! because `rovs_openflow::VConn` only supports active (outbound) connections.

use anyhow::{Context, Result};
use bytes::Bytes;
use rovs_openflow::{ActionList, Flow, Match, Message, MessageType, OutputPort, Version};
use rovs_transport::Reconnect;
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};

// ── OF1.3 constants ────────────────────────────────────────────────────────────

/// Multipart type: port description.
const OFPMP_PORT_DESC: u16 = 13;
/// "All" output port — used when out_port is not restricted.
const OFPP_ANY: u32 = 0xFFFF_FFFF;

// ── Wire helpers ──────────────────────────────────────────────────────────────

/// Build a raw OF1.3 message with an 8-byte header and `body`.
fn build_raw_msg(msg_type: MessageType, xid: u32, body: &[u8]) -> Vec<u8> {
    let msg = Message::new(Version::Of13, msg_type, xid, Bytes::copy_from_slice(body));
    msg.encode().to_vec()
}

/// Build an OF1.3 Hello message.
fn build_hello(xid: u32) -> Vec<u8> {
    build_raw_msg(MessageType::Hello, xid, &[])
}

/// Build an OF1.3 FeaturesRequest message.
fn build_features_request(xid: u32) -> Vec<u8> {
    build_raw_msg(MessageType::FeaturesRequest, xid, &[])
}

/// Build an OF1.3 PortDesc multipart request.
///
/// Body: type(2) + flags(2) + pad(4) = 8 bytes.
fn build_port_desc_request(xid: u32) -> Vec<u8> {
    let mut body = [0u8; 8];
    body[0..2].copy_from_slice(&OFPMP_PORT_DESC.to_be_bytes());
    build_raw_msg(MessageType::MultipartRequest, xid, &body)
}

/// Build an OF1.3 EchoReply that mirrors the request payload.
fn build_echo_reply(xid: u32, payload: &[u8]) -> Vec<u8> {
    build_raw_msg(MessageType::EchoReply, xid, payload)
}

/// Build an OF1.3 FlowMod DELETE ALL (wildcard match, all tables).
fn build_flow_mod_delete_all(xid: u32) -> Vec<u8> {
    let flow = Flow::delete();
    let msg = flow.to_message(Version::Of13, xid);
    msg.encode().to_vec()
}

/// Build an OF1.3 FlowMod ADD: match `in_port`, output to `out_port`.
pub fn build_flow_mod_add(in_port: u32, out_port: u32, priority: u16, xid: u32) -> Vec<u8> {
    let match_fields = Match::new().in_port(in_port);
    let actions = ActionList::new().output(OutputPort::Port(out_port));
    let flow = Flow::add()
        .priority(priority)
        .match_fields(match_fields)
        .actions(actions);
    let msg = flow.to_message(Version::Of13, xid);
    msg.encode().to_vec()
}

// ── Raw message receive ───────────────────────────────────────────────────────

/// A raw inbound OpenFlow message (header parsed, body buffered).
struct RawMsg {
    msg_type: u8,
    xid: u32,
    payload: Vec<u8>,
}

/// Read one complete OpenFlow message from `stream`.
async fn recv_msg(stream: &mut TcpStream) -> Result<RawMsg> {
    let mut hdr = [0u8; 8];
    stream
        .read_exact(&mut hdr)
        .await
        .context("reading OF header")?;

    let msg_type = hdr[1];
    let length = u16::from_be_bytes([hdr[2], hdr[3]]) as usize;
    let xid = u32::from_be_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]);
    let payload_len = length.saturating_sub(8);

    let mut payload = vec![0u8; payload_len];
    if payload_len > 0 {
        stream
            .read_exact(&mut payload)
            .await
            .context("reading OF payload")?;
    }

    Ok(RawMsg {
        msg_type,
        xid,
        payload,
    })
}

/// Write raw bytes to `stream`.
async fn send_msg(stream: &mut TcpStream, bytes: &[u8]) -> Result<()> {
    stream.write_all(bytes).await.context("sending OF message")
}

// ── Port discovery ─────────────────────────────────────────────────────────────

/// Send a PortDesc request and parse all replies into `{port_name → ofport_no}`.
async fn discover_ports(stream: &mut TcpStream, xid: u32) -> Result<HashMap<String, u32>> {
    send_msg(stream, &build_port_desc_request(xid)).await?;

    let mut ports: HashMap<String, u32> = HashMap::new();

    loop {
        let msg = recv_msg(stream).await?;
        match msg.msg_type {
            // Echo request — must reply to stay alive during discovery.
            2 /* EchoRequest */ => {
                send_msg(stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            // MultipartReply (19)
            19 => {
                if msg.payload.len() < 8 {
                    break;
                }
                let reply_type = u16::from_be_bytes([msg.payload[0], msg.payload[1]]);
                let flags = u16::from_be_bytes([msg.payload[2], msg.payload[3]]);

                if reply_type == OFPMP_PORT_DESC {
                    // OF1.3 ofp_port = 64 bytes:
                    // port_no(4) pad(4) hw_addr(6) pad(2) name(16) config(4) state(4)
                    // curr(4) advertised(4) supported(4) peer(4) curr_speed(4) max_speed(4)
                    let body = &msg.payload[8..];
                    for chunk in body.chunks_exact(64) {
                        let port_no =
                            u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
                        let name = String::from_utf8_lossy(&chunk[16..32])
                            .trim_end_matches('\0')
                            .to_string();
                        if !name.is_empty() && port_no < OFPP_ANY {
                            ports.insert(name, port_no);
                        }
                    }
                    // bit 0 of flags = OFPMPF_REPLY_MORE
                    if flags & 1 == 0 {
                        break;
                    }
                } else {
                    break;
                }
            }
            _ => break,
        }
    }

    Ok(ports)
}

// ── Connection handler ────────────────────────────────────────────────────────

/// Handle one inbound OVS connection: handshake → port discovery → flow install → keepalive.
async fn handle_connection(
    mut stream: TcpStream,
    flows: Arc<Vec<(String, String, u16)>>,
) -> Result<()> {
    let mut xid: u32 = 1;

    // 1. Receive Hello from OVS.
    let hello = recv_msg(&mut stream).await?;
    if hello.msg_type != 0 {
        anyhow::bail!("expected Hello (type 0), got msg_type={}", hello.msg_type);
    }

    // 2. Send Hello.
    send_msg(&mut stream, &build_hello(xid)).await?;
    xid += 1;

    // 3. Send FeaturesRequest; wait for FeaturesReply (type 6), echo any pings.
    send_msg(&mut stream, &build_features_request(xid)).await?;
    xid += 1;

    loop {
        let msg = recv_msg(&mut stream).await?;
        match msg.msg_type {
            2 /* EchoRequest */ => {
                send_msg(&mut stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            6 /* FeaturesReply */ => break,
            _ => {}
        }
    }

    // 4. Discover ports via PortDesc multipart.
    let port_map = discover_ports(&mut stream, xid).await?;
    xid += 1;

    log::info!(
        "OF controller: discovered {} ports: {:?}",
        port_map.len(),
        port_map.keys().collect::<Vec<_>>()
    );

    // 5. Delete all existing flows.
    send_msg(&mut stream, &build_flow_mod_delete_all(xid)).await?;
    xid += 1;

    // 6. Install configured flows.
    let mut installed = 0u32;
    for (in_name, out_name, priority) in flows.iter() {
        match (
            port_map.get(in_name.as_str()),
            port_map.get(out_name.as_str()),
        ) {
            (Some(&in_port), Some(&out_port)) => {
                send_msg(
                    &mut stream,
                    &build_flow_mod_add(in_port, out_port, *priority, xid),
                )
                .await?;
                xid += 1;
                installed += 1;
                log::info!(
                    "OF controller: installed flow {} (port {}) → {} (port {}), priority={}",
                    in_name,
                    in_port,
                    out_name,
                    out_port,
                    priority
                );
            }
            _ => {
                log::warn!(
                    "OF controller: port not found for flow {} → {} (known: {:?})",
                    in_name,
                    out_name,
                    port_map.keys().collect::<Vec<_>>()
                );
            }
        }
    }

    log::info!(
        "OF controller: {} flows installed; entering keepalive loop",
        installed
    );

    // 7. Keepalive loop — reply to Echo requests indefinitely.
    loop {
        let msg = recv_msg(&mut stream).await?;
        if msg.msg_type == 2
        /* EchoRequest */
        {
            send_msg(&mut stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
        }
    }
}

// ── Public API ────────────────────────────────────────────────────────────────

/// OpenFlow 1.3 controller — accepts connections from OVS and installs flows.
///
/// OVS connects *to* the controller (not the other way around).
/// Configure OVS with: `ovs-vsctl set-controller ovsbr0 tcp:<listen_addr>`
pub struct OpenFlowController {
    listen_addr: SocketAddr,
    flows: Vec<(String, String, u16)>,
}

impl OpenFlowController {
    /// Create a new controller that will listen on `listen_addr`.
    pub fn new(listen_addr: SocketAddr) -> Self {
        Self {
            listen_addr,
            flows: Vec::new(),
        }
    }

    /// Add a bidirectional forwarding pair (installs two flows: A→B and B→A).
    pub fn add_port_pair(mut self, port_a: &str, port_b: &str, priority: u16) -> Self {
        self.flows
            .push((port_a.to_string(), port_b.to_string(), priority));
        self.flows
            .push((port_b.to_string(), port_a.to_string(), priority));
        self
    }

    /// Add a single directed flow (in_port → out_port).
    pub fn add_flow(mut self, in_port: &str, out_port: &str, priority: u16) -> Self {
        self.flows
            .push((in_port.to_string(), out_port.to_string(), priority));
        self
    }

    /// Run the controller — listens for OVS connections and re-programs flows on each reconnect.
    ///
    /// Each spawned connection handler maintains its own `Reconnect` state machine so
    /// that rapid repeated failures (e.g. OVS flapping) are logged with backoff information
    /// rather than silently spinning.
    pub async fn run(self) -> Result<()> {
        let listener = TcpListener::bind(self.listen_addr)
            .await
            .with_context(|| format!("binding OpenFlow controller on {}", self.listen_addr))?;

        log::info!("OpenFlow controller listening on {}", self.listen_addr);

        let flows = Arc::new(self.flows);

        loop {
            let (stream, peer) = listener.accept().await?;
            let flows = flows.clone();
            log::info!("OpenFlow controller: OVS connected from {}", peer);

            tokio::spawn(async move {
                // Per-connection reconnection tracker.  OVS is the active side so
                // we don't drive the reconnect loop ourselves — we just record state
                // and log when failures come in rapidly so operators see backoff hints.
                let mut reconnect = Reconnect::new();
                reconnect.set_max_backoff(Duration::from_secs(30));
                reconnect.connecting();

                match handle_connection(stream, flows).await {
                    Ok(()) => {
                        // Clean close — mark disconnected so next accept starts fresh.
                        reconnect.disconnected();
                        log::info!("OF controller: connection from {} closed cleanly", peer);
                    }
                    Err(e) => {
                        reconnect.disconnected();
                        reconnect.increase_backoff();
                        log::warn!(
                            "OF controller: connection from {} ended with error \
                             (next OVS reconnect backoff hint: {:?}): {:#}",
                            peer,
                            reconnect.current_backoff(),
                            e
                        );
                    }
                }
            });
        }
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_flow_mod_add_length() {
        let msg = build_flow_mod_add(6, 7, 100, 1);
        let declared_len = u16::from_be_bytes([msg[2], msg[3]]) as usize;
        assert_eq!(declared_len, msg.len(), "declared length must match actual");
        // OF1.3 version byte
        assert_eq!(msg[0], 0x04);
        // FlowMod type = 14
        assert_eq!(msg[1], 14);
    }

    #[test]
    fn test_flow_mod_delete_all() {
        let msg = build_flow_mod_delete_all(1);
        let declared_len = u16::from_be_bytes([msg[2], msg[3]]) as usize;
        assert_eq!(declared_len, msg.len(), "declared length must match actual");
        assert_eq!(msg[0], 0x04); // OF1.3
        assert_eq!(msg[1], 14); // FlowMod
    }
}

//! Virtual connection (VConn) for OpenFlow.

use bytes::{Bytes, BytesMut};
use tokio::io::{AsyncReadExt, AsyncWriteExt};

use rovs_transport::{Address, Stream};

use crate::error::OfError;
use crate::flow_monitor::{parse_flow_monitor_reply, FlowMonitorRequest, FlowUpdate};
use crate::multipart::{parse_flow_stats_reply, FlowStatsEntry, FlowStatsRequest};
use crate::packet_in::PacketIn;
use crate::packet_out::PacketOut;
use crate::{Error, Flow, Header, Message, MessageType, Result, Version};

/// An OpenFlow virtual connection.
pub struct VConn {
    stream: Stream,
    version: Version,
    next_xid: u32,
}

impl VConn {
    /// Connect to an OpenFlow switch.
    pub async fn connect(addr: &Address) -> Result<Self> {
        let stream = Stream::connect(addr).await?;

        let mut conn = Self {
            stream,
            version: Version::Of13, // Will be negotiated
            next_xid: 1,
        };

        conn.handshake().await?;
        Ok(conn)
    }

    /// Get the negotiated OpenFlow version.
    pub fn version(&self) -> Version {
        self.version
    }

    /// Perform the OpenFlow handshake.
    async fn handshake(&mut self) -> Result<()> {
        // Send Hello
        let hello = Message::new(
            Version::Of13,
            MessageType::Hello,
            self.next_xid(),
            Bytes::new(),
        );
        self.send_message(&hello).await?;

        // Receive Hello
        let reply = self.recv_message().await?;
        if reply.header.msg_type != MessageType::Hello {
            return Err(Error::InvalidMessage("expected Hello".into()));
        }

        // Use the lower of the two versions
        self.version = std::cmp::min(self.version, reply.header.version);

        Ok(())
    }

    /// Get the next transaction ID.
    fn next_xid(&mut self) -> u32 {
        let xid = self.next_xid;
        self.next_xid = self.next_xid.wrapping_add(1);
        xid
    }

    /// Send a message.
    pub async fn send_message(&mut self, msg: &Message) -> Result<()> {
        let bytes = msg.encode();
        self.stream.write_all(&bytes).await?;
        self.stream.flush().await?;
        Ok(())
    }

    /// Receive a message.
    pub async fn recv_message(&mut self) -> Result<Message> {
        // Read header
        let mut header_buf = [0u8; Header::SIZE];
        self.stream.read_exact(&mut header_buf).await?;
        let header = Header::decode(&mut Bytes::copy_from_slice(&header_buf))?;

        // Read body
        let body_len = header.length as usize - Header::SIZE;
        let mut body = BytesMut::zeroed(body_len);
        if body_len > 0 {
            self.stream.read_exact(&mut body).await?;
        }

        Ok(Message {
            header,
            body: body.freeze(),
        })
    }

    /// Check if a message is an error and return the appropriate error.
    fn check_error(msg: &Message) -> Result<()> {
        if msg.header.msg_type == MessageType::Error {
            let of_error = OfError::parse(&msg.body)?;
            return Err(Error::OfError(of_error));
        }
        Ok(())
    }

    /// Send a flow modification to the switch.
    ///
    /// This sends the FlowMod message asynchronously without waiting for
    /// confirmation. Use `send_flow_sync` if you need to ensure the flow
    /// was successfully installed.
    pub async fn send_flow(&mut self, flow: &Flow) -> Result<()> {
        let xid = self.next_xid();
        let msg = flow.to_message(self.version, xid);
        self.send_message(&msg).await
    }

    /// Send a flow modification and wait for confirmation.
    ///
    /// Sends the FlowMod followed by a barrier request, then waits for
    /// the barrier reply. If an error occurs (e.g., invalid flow), it
    /// will be returned.
    ///
    /// This ensures the flow is installed (or rejected) before returning.
    pub async fn send_flow_sync(&mut self, flow: &Flow) -> Result<()> {
        // Send the flow
        let flow_xid = self.next_xid();
        let flow_msg = flow.to_message(self.version, flow_xid);
        self.send_message(&flow_msg).await?;

        // Send barrier
        let barrier_xid = self.next_xid();
        let barrier_msg =
            Message::new(self.version, MessageType::BarrierRequest, barrier_xid, Bytes::new());
        self.send_message(&barrier_msg).await?;

        // Wait for response - could be error or barrier reply
        loop {
            let reply = self.recv_message().await?;

            // Check for error (could be from flow or barrier)
            Self::check_error(&reply)?;

            // If we got the barrier reply, flow was successfully installed
            if reply.header.msg_type == MessageType::BarrierReply {
                return Ok(());
            }

            // Handle echo requests while waiting (keep-alive)
            if reply.header.msg_type == MessageType::EchoRequest {
                let echo_reply = Message::new(
                    self.version,
                    MessageType::EchoReply,
                    reply.header.xid,
                    reply.body.clone(),
                );
                self.send_message(&echo_reply).await?;
            }

            // Skip other async messages (PacketIn, PortStatus, FlowRemoved)
            // In a full implementation, these would be queued for processing
        }
    }

    /// Send an echo request and wait for reply.
    pub async fn echo(&mut self) -> Result<()> {
        let xid = self.next_xid();
        let request = Message::new(self.version, MessageType::EchoRequest, xid, Bytes::new());
        self.send_message(&request).await?;

        let reply = self.recv_message().await?;
        if reply.header.msg_type != MessageType::EchoReply {
            return Err(Error::InvalidMessage("expected EchoReply".into()));
        }
        if reply.header.xid != xid {
            return Err(Error::InvalidMessage("xid mismatch".into()));
        }

        Ok(())
    }

    /// Send a barrier and wait for reply.
    pub async fn barrier(&mut self) -> Result<()> {
        let xid = self.next_xid();
        let request = Message::new(self.version, MessageType::BarrierRequest, xid, Bytes::new());
        self.send_message(&request).await?;

        loop {
            let reply = self.recv_message().await?;

            // Check for errors
            Self::check_error(&reply)?;

            if reply.header.msg_type == MessageType::BarrierReply {
                return Ok(());
            }

            // Handle echo requests while waiting
            if reply.header.msg_type == MessageType::EchoRequest {
                let echo_reply = Message::new(
                    self.version,
                    MessageType::EchoReply,
                    reply.header.xid,
                    reply.body.clone(),
                );
                self.send_message(&echo_reply).await?;
            }

            // Skip other async messages
        }
    }

    /// Dump all flows from the switch.
    ///
    /// Returns all flow entries from all tables. Use `dump_flows_filtered`
    /// for more specific queries.
    pub async fn dump_flows(&mut self) -> Result<Vec<FlowStatsEntry>> {
        self.dump_flows_filtered(FlowStatsRequest::new()).await
    }

    /// Dump flows matching the given filter.
    ///
    /// The request can filter by table ID, match fields, cookie, etc.
    pub async fn dump_flows_filtered(
        &mut self,
        request: FlowStatsRequest,
    ) -> Result<Vec<FlowStatsEntry>> {
        let xid = self.next_xid();
        let msg = request.to_message(self.version, xid);
        self.send_message(&msg).await?;

        let mut all_entries = Vec::new();

        // Receive multipart replies until we get one without MORE flag
        loop {
            let reply = self.recv_message().await?;

            // Check for errors
            Self::check_error(&reply)?;

            // Handle echo requests
            if reply.header.msg_type == MessageType::EchoRequest {
                let echo_reply = Message::new(
                    self.version,
                    MessageType::EchoReply,
                    reply.header.xid,
                    reply.body.clone(),
                );
                self.send_message(&echo_reply).await?;
                continue;
            }

            // Skip non-multipart replies
            if reply.header.msg_type != MessageType::MultipartReply {
                continue;
            }

            // Parse the flow stats reply
            let (entries, has_more) = parse_flow_stats_reply(&reply.body)?;
            all_entries.extend(entries);

            if !has_more {
                break;
            }
        }

        Ok(all_entries)
    }

    /// Wait for and receive a Packet-In message.
    ///
    /// This blocks until a Packet-In message is received, handling
    /// echo requests and skipping other message types.
    pub async fn recv_packet_in(&mut self) -> Result<PacketIn> {
        loop {
            let msg = self.recv_message().await?;

            // Check for errors
            Self::check_error(&msg)?;

            // Handle echo requests (keep-alive)
            if msg.header.msg_type == MessageType::EchoRequest {
                let echo_reply = Message::new(
                    self.version,
                    MessageType::EchoReply,
                    msg.header.xid,
                    msg.body.clone(),
                );
                self.send_message(&echo_reply).await?;
                continue;
            }

            // Process Packet-In
            if msg.header.msg_type == MessageType::PacketIn {
                return PacketIn::parse(msg.body);
            }

            // Skip other async messages (PortStatus, FlowRemoved)
        }
    }

    /// Try to receive a Packet-In message without blocking.
    ///
    /// Returns `Ok(Some(packet_in))` if a Packet-In is available,
    /// `Ok(None)` if a different message was received (and handled),
    /// or an error if something went wrong.
    ///
    /// Note: This still blocks on the read itself; it just doesn't loop
    /// waiting specifically for a Packet-In.
    pub async fn try_recv_packet_in(&mut self) -> Result<Option<PacketIn>> {
        let msg = self.recv_message().await?;

        // Check for errors
        Self::check_error(&msg)?;

        // Handle echo requests
        if msg.header.msg_type == MessageType::EchoRequest {
            let echo_reply = Message::new(
                self.version,
                MessageType::EchoReply,
                msg.header.xid,
                msg.body.clone(),
            );
            self.send_message(&echo_reply).await?;
            return Ok(None);
        }

        // Process Packet-In
        if msg.header.msg_type == MessageType::PacketIn {
            return Ok(Some(PacketIn::parse(msg.body)?));
        }

        // Other message types
        Ok(None)
    }

    /// Register a flow monitor and receive the initial snapshot.
    ///
    /// Sends the monitor request and collects the initial flow updates
    /// (if `NXFMF_INITIAL` flag was set in the request). After this returns,
    /// use `recv_flow_updates()` to receive ongoing updates.
    ///
    /// Use a dedicated VConn for monitoring — the monitor produces a
    /// continuous stream that occupies the connection's recv path.
    pub async fn monitor_flows(
        &mut self,
        request: FlowMonitorRequest,
    ) -> Result<Vec<FlowUpdate>> {
        let xid = self.next_xid();
        let msg = request.to_message(self.version, xid);
        self.send_message(&msg).await?;

        let mut all_updates = Vec::new();

        // Collect initial snapshot (multipart replies until no MORE flag)
        loop {
            let reply = self.recv_message().await?;

            Self::check_error(&reply)?;

            if reply.header.msg_type == MessageType::EchoRequest {
                let echo_reply = Message::new(
                    self.version,
                    MessageType::EchoReply,
                    reply.header.xid,
                    reply.body.clone(),
                );
                self.send_message(&echo_reply).await?;
                continue;
            }

            if reply.header.msg_type != MessageType::MultipartReply {
                continue;
            }

            let (updates, has_more) = parse_flow_monitor_reply(&reply.body)?;
            all_updates.extend(updates);

            if !has_more {
                break;
            }
        }

        Ok(all_updates)
    }

    /// Receive the next batch of flow monitor updates.
    ///
    /// Blocks until flow update messages are received from OVS.
    /// Handles echo requests internally. Returns the parsed updates.
    ///
    /// Call this in a loop after `monitor_flows()` to receive ongoing
    /// flow change notifications.
    pub async fn recv_flow_updates(&mut self) -> Result<Vec<FlowUpdate>> {
        loop {
            let msg = self.recv_message().await?;

            Self::check_error(&msg)?;

            if msg.header.msg_type == MessageType::EchoRequest {
                let echo_reply = Message::new(
                    self.version,
                    MessageType::EchoReply,
                    msg.header.xid,
                    msg.body.clone(),
                );
                self.send_message(&echo_reply).await?;
                continue;
            }

            if msg.header.msg_type == MessageType::MultipartReply {
                let (updates, _has_more) = parse_flow_monitor_reply(&msg.body)?;
                if !updates.is_empty() {
                    return Ok(updates);
                }
            }

            // Skip other message types (PacketIn, PortStatus, FlowRemoved, etc.)
        }
    }

    /// Send a Packet-Out message.
    ///
    /// This injects a packet into the switch's datapath or releases
    /// a buffered packet with the specified actions.
    pub async fn send_packet_out(&mut self, packet_out: &PacketOut) -> Result<()> {
        let xid = self.next_xid();
        let msg = packet_out.to_message(self.version, xid);
        self.send_message(&msg).await
    }
}

