//! JSON-RPC protocol implementation for OVSDB.
//!
//! Provides message types and connection handling for the JSON-RPC 1.0
//! protocol used by OVSDB (RFC 7047).

mod connection;
mod error;
mod message;

pub use connection::Connection;
pub use error::Error;
pub use message::{Message, Request, Response, RpcError, RpcId};

pub type Result<T> = std::result::Result<T, Error>;

//! JSON-RPC 1.0 connection handling for OVSDB.
//!
//! This module implements JSON-RPC communication with OVSDB servers.
//!
//! # Important Implementation Detail
//!
//! OVSDB servers do **not** send newlines after JSON responses. Instead, this
//! implementation uses brace-depth tracking to detect complete JSON objects.
//! The parser tracks `{` and `}` characters (respecting string contents and escapes)
//! to determine when a complete message has been received.

use std::collections::VecDeque;
use std::sync::atomic::{AtomicU64, Ordering};

use serde_json::Value;
use tokio::io::{AsyncReadExt, AsyncWriteExt, BufWriter};

use rovs_transport::Stream;

use crate::{Error, Message, Request, Response, Result, RpcId};

/// A JSON-RPC connection over a transport stream.
///
/// Handles request/response matching and buffers server notifications
/// received while waiting for responses.
pub struct Connection {
    reader: tokio::io::ReadHalf<Stream>,
    writer: BufWriter<tokio::io::WriteHalf<Stream>>,
    read_buf: Vec<u8>,
    next_id: AtomicU64,
    /// Pending notifications from server (received while waiting for response)
    pending_notifications: VecDeque<Request>,
}

impl Connection {
    /// Create a new connection from a transport stream.
    ///
    /// The stream is split into read/write halves for concurrent I/O.
    pub fn new(stream: Stream) -> Self {
        let (read_half, write_half) = tokio::io::split(stream);
        Self {
            reader: read_half,
            writer: BufWriter::new(write_half),
            read_buf: Vec::with_capacity(4096),
            next_id: AtomicU64::new(1),
            pending_notifications: VecDeque::new(),
        }
    }

    /// Get the next request ID.
    pub fn next_id(&self) -> u64 {
        self.next_id.fetch_add(1, Ordering::SeqCst)
    }

    /// Send a request and wait for the matching response.
    ///
    /// Any notifications received while waiting are buffered and can be
    /// retrieved via [`pop_notification`](Self::pop_notification).
    ///
    /// Returns the result value, or an error if the RPC failed.
    pub async fn transact(&mut self, method: &str, params: Value) -> Result<Value> {
        let id = self.next_id();
        let request = Request::new(method, params, id);

        self.send_message(&Message::Request(request)).await?;
        let response = self.recv_response(id).await?;

        if let Some(error) = response.error {
            return Err(Error::Rpc(error));
        }

        Ok(response.result.unwrap_or(Value::Null))
    }

    /// Send a notification (no response expected).
    pub async fn notify(&mut self, method: &str, params: Value) -> Result<()> {
        let request = Request::notification(method, params);
        self.send_message(&Message::Request(request)).await
    }

    /// Send a message.
    pub async fn send_message(&mut self, msg: &Message) -> Result<()> {
        let json = serde_json::to_string(msg)?;
        tracing::debug!("TX: {}", json);
        self.writer.write_all(json.as_bytes()).await?;
        self.writer.write_all(b"\n").await?;
        self.writer.flush().await?;
        Ok(())
    }

    /// Receive a response, buffering any notifications received in the meantime.
    async fn recv_response(&mut self, expected_id: u64) -> Result<Response> {
        let expected = RpcId::Number(expected_id);
        loop {
            let msg = self.recv_message().await?;

            match msg {
                Message::Response(resp) => {
                    if resp.id != expected {
                        return Err(Error::UnexpectedId {
                            expected: expected_id,
                            got: resp.id.as_u64().unwrap_or(0),
                        });
                    }
                    return Ok(resp);
                }
                Message::Request(req) => {
                    // Server notification - buffer it for later processing
                    tracing::debug!("Buffering notification: {}", req.method);
                    self.pending_notifications.push_back(req);
                }
            }
        }
    }

    /// Receive a single message from the connection.
    ///
    /// Uses brace-depth tracking to detect complete JSON objects since
    /// OVSDB servers don't send newlines after responses. Handles:
    /// - Nested JSON objects
    /// - Strings containing braces
    /// - Escaped characters within strings
    ///
    /// Returns either a [`Request`] (notification from server) or
    /// [`Response`] (reply to our request).
    pub async fn recv_message(&mut self) -> Result<Message> {
        tracing::debug!("Waiting to receive message...");

        // Read bytes until we have a complete JSON object
        let mut depth = 0i32;
        let mut in_string = false;
        let mut escape_next = false;
        let mut json_start = None;

        loop {
            // Try to parse from existing buffer first
            for (i, &byte) in self.read_buf.iter().enumerate() {
                if json_start.is_none() && byte == b'{' {
                    json_start = Some(i);
                }

                if json_start.is_some() {
                    if escape_next {
                        escape_next = false;
                        continue;
                    }

                    match byte {
                        b'\\' if in_string => escape_next = true,
                        b'"' => in_string = !in_string,
                        b'{' if !in_string => depth += 1,
                        b'}' if !in_string => {
                            depth -= 1;
                            if depth == 0 {
                                // Found complete JSON object
                                let start = json_start.unwrap();
                                let json_bytes = &self.read_buf[start..=i];
                                let json_str = String::from_utf8_lossy(json_bytes);
                                tracing::debug!("RX: {}", json_str);

                                let msg: Message = serde_json::from_slice(json_bytes)?;

                                // Remove consumed bytes from buffer
                                self.read_buf.drain(..=i);

                                return Ok(msg);
                            }
                        }
                        _ => {}
                    }
                }
            }

            // Need more data - reset parsing state since we'll re-scan from start
            depth = 0;
            in_string = false;
            escape_next = false;
            json_start = None;

            let mut buf = [0u8; 4096];
            tracing::debug!("Reading more data...");
            let n = self.reader.read(&mut buf).await?;
            tracing::debug!("Read {} bytes", n);

            if n == 0 {
                return Err(Error::ConnectionClosed);
            }

            self.read_buf.extend_from_slice(&buf[..n]);
            tracing::debug!("Buffer now has {} bytes", self.read_buf.len());
        }
    }

    /// Check if there are buffered notifications from the server.
    ///
    /// Notifications received while waiting for a response are buffered here.
    pub fn has_pending_notifications(&self) -> bool {
        !self.pending_notifications.is_empty()
    }

    /// Get the count of pending notifications.
    pub fn pending_notification_count(&self) -> usize {
        self.pending_notifications.len()
    }

    /// Pop the next buffered notification (FIFO order).
    ///
    /// Returns `None` if no notifications are pending.
    pub fn pop_notification(&mut self) -> Option<Request> {
        self.pending_notifications.pop_front()
    }

    /// Drain all buffered notifications, returning an iterator.
    ///
    /// Clears the notification buffer and yields all pending notifications.
    pub fn drain_notifications(&mut self) -> impl Iterator<Item = Request> + '_ {
        self.pending_notifications.drain(..)
    }
}

//! JSON-RPC message types.

use serde::de::{self, Deserializer};
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// JSON-RPC request/response ID.
///
/// Can be a number, string, or null. OVSDB uses both numeric IDs (for our requests)
/// and string IDs (e.g., "echo" for server-initiated echo requests).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum RpcId {
    /// Numeric ID (used by this client)
    Number(u64),
    /// String ID (used by some server requests like "echo")
    String(String),
}

impl RpcId {
    /// Get as u64 if this is a numeric ID.
    pub fn as_u64(&self) -> Option<u64> {
        match self {
            Self::Number(n) => Some(*n),
            Self::String(_) => None,
        }
    }
}

impl From<u64> for RpcId {
    fn from(n: u64) -> Self {
        Self::Number(n)
    }
}

impl From<&str> for RpcId {
    fn from(s: &str) -> Self {
        Self::String(s.to_owned())
    }
}

/// A JSON-RPC message (request, response, or notification).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Message {
    /// A request expecting a response
    Request(Request),
    /// A response to a request
    Response(Response),
}

/// A JSON-RPC request.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Request {
    /// The method name
    pub method: String,
    /// The parameters
    pub params: Value,
    /// The request ID (None for notifications)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<RpcId>,
}

impl Request {
    /// Create a new request.
    pub fn new(method: impl Into<String>, params: Value, id: u64) -> Self {
        Self {
            method: method.into(),
            params,
            id: Some(RpcId::Number(id)),
        }
    }

    /// Create a notification (no response expected).
    pub fn notification(method: impl Into<String>, params: Value) -> Self {
        Self {
            method: method.into(),
            params,
            id: None,
        }
    }

    /// Check if this is a notification.
    pub fn is_notification(&self) -> bool {
        self.id.is_none()
    }
}

/// A JSON-RPC response.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Response {
    /// The result (if successful)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub result: Option<Value>,
    /// The error (if failed)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<RpcError>,
    /// The request ID this responds to
    pub id: RpcId,
}

impl Response {
    /// Create a success response.
    pub fn success(id: impl Into<RpcId>, result: Value) -> Self {
        Self {
            result: Some(result),
            error: None,
            id: id.into(),
        }
    }

    /// Create an error response.
    pub fn error(id: impl Into<RpcId>, error: RpcError) -> Self {
        Self {
            result: None,
            error: Some(error),
            id: id.into(),
        }
    }

    /// Check if this response is an error.
    pub fn is_error(&self) -> bool {
        self.error.is_some()
    }
}

/// A JSON-RPC error object.
///
/// Handles two wire formats:
/// - **OVSDB**: `{"error": "message", "details": "extra info"}`
/// - **unixctl**: `"plain error string"`
///
/// A plain string deserializes to `RpcError { error: "the string", details: None }`.
#[derive(Debug, Clone, Serialize)]
pub struct RpcError {
    /// Error message
    pub error: String,
    /// Optional additional details
    #[serde(skip_serializing_if = "Option::is_none")]
    pub details: Option<String>,
}

impl<'de> Deserialize<'de> for RpcError {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let value = serde_json::Value::deserialize(deserializer)?;
        match value {
            serde_json::Value::String(s) => Ok(Self {
                error: s,
                details: None,
            }),
            serde_json::Value::Object(map) => {
                let error = map
                    .get("error")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("unknown error")
                    .to_owned();
                let details = map
                    .get("details")
                    .and_then(serde_json::Value::as_str)
                    .map(String::from);
                Ok(Self { error, details })
            }
            other => Err(de::Error::custom(format!(
                "expected string or object for RpcError, got {other}"
            ))),
        }
    }
}

impl std::fmt::Display for RpcError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.error)?;
        if let Some(details) = &self.details {
            write!(f, ": {details}")?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rpc_error_from_plain_string() {
        // unixctl format: {"error": "unknown command"}
        let json = r#""unknown command""#;
        let err: RpcError = serde_json::from_str(json).unwrap();
        assert_eq!(err.error, "unknown command");
        assert!(err.details.is_none());
    }

    #[test]
    fn rpc_error_from_object() {
        // OVSDB format: {"error": {"error": "constraint violation", "details": "..."}}
        let json = r#"{"error": "constraint violation", "details": "column name is immutable"}"#;
        let err: RpcError = serde_json::from_str(json).unwrap();
        assert_eq!(err.error, "constraint violation");
        assert_eq!(err.details.as_deref(), Some("column name is immutable"));
    }

    #[test]
    fn rpc_error_from_object_no_details() {
        let json = r#"{"error": "some error"}"#;
        let err: RpcError = serde_json::from_str(json).unwrap();
        assert_eq!(err.error, "some error");
        assert!(err.details.is_none());
    }

    #[test]
    fn rpc_error_display() {
        let err = RpcError {
            error: "bad request".to_owned(),
            details: Some("missing field".to_owned()),
        };
        assert_eq!(err.to_string(), "bad request: missing field");

        let err = RpcError {
            error: "not found".to_owned(),
            details: None,
        };
        assert_eq!(err.to_string(), "not found");
    }

    #[test]
    fn response_with_string_error() {
        // Full unixctl response with plain string error
        let json = r#"{"result": null, "error": "unknown command dpif/bad", "id": 0}"#;
        let resp: Response = serde_json::from_str(json).unwrap();
        assert!(resp.is_error());
        assert_eq!(resp.error.unwrap().error, "unknown command dpif/bad");
    }

    #[test]
    fn response_with_object_error() {
        // Full OVSDB response with object error
        let json = r#"{"result": null, "error": {"error": "constraint violation", "details": "x"}, "id": 1}"#;
        let resp: Response = serde_json::from_str(json).unwrap();
        assert!(resp.is_error());
        let err = resp.error.unwrap();
        assert_eq!(err.error, "constraint violation");
        assert_eq!(err.details.as_deref(), Some("x"));
    }

    #[test]
    fn response_with_null_error() {
        // Successful response
        let json = r#"{"result": "some output", "error": null, "id": 0}"#;
        let resp: Response = serde_json::from_str(json).unwrap();
        assert!(!resp.is_error());
        assert!(resp.error.is_none());
    }
}

//! JSON-RPC error types.

use thiserror::Error;

use crate::message::RpcError;

/// Errors that can occur in JSON-RPC communication.
#[derive(Debug, Error)]
pub enum Error {
    /// Transport error
    #[error("transport error: {0}")]
    Transport(#[from] rovs_transport::Error),

    /// JSON serialization/deserialization error
    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),

    /// I/O error
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),

    /// RPC error returned by server
    #[error("RPC error: {0}")]
    Rpc(RpcError),

    /// Unexpected response ID
    #[error("unexpected response ID: expected {expected}, got {got}")]
    UnexpectedId { expected: u64, got: u64 },

    /// Connection closed
    #[error("connection closed")]
    ConnectionClosed,
}

