            .entry(schema_name.clone())
            .or_insert_with(Vec::new)
            .push(schema.clone());

        // Record audit entry
        self.record_audit(
            &schema_name,
            SchemaChangeType::Registered,
            &format!("Registered schema version {}", schema_version),
        );

