              "certificateFile": "/etc/xray/tls.crt",
              "keyFile": "/etc/xray/tls.key"
            }
          ]
        }
      }
    },
    {
      "tag": "op-grpc-tls",
      "listen": "\${EXT_IP}",
      "port": 50051,
      "protocol": "vless",
      "settings": {
        "clients": [
          { "id": "f997ea91-94bb-4078-b172-649cd21a7647" }
        ],
        "decryption": "none",
        "fallbacks": [
          { "dest": "10.200.0.1:50051" }
        ]
      },
      "streamSettings": {
        "network": "tcp",
        "security": "tls",
        "tlsSettings": {
          "alpn": ["h2"],
          "certificates": [
            {
              "certificateFile": "/etc/xray/tls.crt",
              "keyFile": "/etc/xray/tls.key"
            }
          ]
        }
      }
    },
    {
      "tag": "ghostbridge-reality",
      "listen": "\${EXT_IP}",
      "port": 8443,
      "protocol": "vless",
      "settings": {
        "clients": [
          {
            "id": "f997ea91-94bb-4078-b172-649cd21a7647",
            "flow": "xtls-rprx-vision"
          }
        ],
        "decryption": "none",
        "fallbacks": [
          { "dest": "10.200.0.1:8080" }
        ]
      },
      "streamSettings": {
        "network": "tcp",
        "security": "reality",
        "realitySettings": {
          "dest": "www.microsoft.com:443",
          "serverNames": ["www.microsoft.com"],
          "privateKey": "*******************************************",
          "shortIds": ["821c52c7ba699c33"]
