EOF

# 3. Setup s6 service
mkdir -p /etc/s6/sv/xray
cat > /etc/s6/sv/xray/run << 'EOF'
#!/bin/execlineb -P
fdmove -c 2 1
/usr/local/bin/xray run -c /etc/xray/config.json
EOF
chmod +x /etc/s6/sv/xray/run

