//! OpenVSwitch D-Bus Daemon
//!
//! Provides D-Bus interfaces for OVSDB and OpenFlow operations via native
//! rovs primitives. This daemon replaces OvsdbClient CLI wrappers with a
//! schema-driven D-Bus service.
//!
//! D-Bus object path: /org/opdbus/v1/plugins/ovsdb
//!
//! Interfaces:
//! - org.opdbus.v1.Ovsdb.JsonRpc (transact method for OVSDB operations)
//! - org.opdbus.v1.Ovsdb.OpenFlow (passive controller absorption)
//!
//! ## Architecture
//!
//! Per AGENTS.md D-Bus-first rules:
//! - All OVS state changes go through D-Bus methods
//! - rovs-jsonrpc::Connection is used for OVSDB JSON-RPC wire protocol
//! - rovs-openflow::VConn handles OpenFlow controller connections
//! - No subprocess spawning - pure Rust native implementation

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, ClientConfig};
use rovs_openflow::VConn;
use std::path::Path;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{info, warn, error};
use zbus::connection::Connection;

mod dbus;
mod ovsdb_proxy;
mod openflow_proxy;

use dbus::OvsdbDBusService;

/// Default OVS socket path
const DEFAULT_OVS_SOCKET: &str = "/var/run/openvswitch/db.sock";

/// Alternative socket paths to try
const OVS_SOCKET_PATHS: &[&str] = &[
    "/run/openvswitch/db.sock",
    "/var/run/openvswitch/db.sock",
];

/// Find the OVS socket path
fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

/// Daemon state holding OVS connections
#[derive(Clone)]
struct DaemonState {
    /// OVSDB client for database operations
    ovsdb: Arc<Mutex<Option<Client>>>,
    /// Socket path for OVSDB connection
    socket_path: String,
}

impl DaemonState {
    fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
        }
    }

    /// Get or create OVSDB client
    async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;

        if guard.is_none() {
            let config = ClientConfig::default()
                .database("Open_vSwitch");

            let addr = format!("unix:{}", self.socket_path);
            let client = Client::connect_with_config(&addr, config)
                .await
                .context("Failed to connect to OVSDB")?;

            info!("Connected to OVSDB at {}", self.socket_path);
            *guard = Some(client);
        }

        Ok(guard)
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon");

    // Find OVS socket
    let socket_path = find_ovs_socket();
    info!("Using OVS socket: {}", socket_path);

    // Create daemon state
    let state = DaemonState::new(socket_path);

    // Test connection early
    if let Err(e) = state.get_ovsdb().await {
        warn!("Could not connect to OVSDB: {}. Daemon will retry on first request.", e);
    }

    // Create D-Bus service
    let service = OvsdbDBusService::new(state);

    // Build D-Bus connection
    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;

    info!("Connected to system D-Bus");

    // Serve the OvsdbDBusService on the connection
    conn.object_server()
        .at("/org/opdbus/v1/plugins/ovsdb", service)
        .await
        .context("Failed to register D-Bus object")?;

    // Request the bus name
    conn.request_name("org.opdbus.v1.plugins.ovsdb")
        .await
        .context("Failed to request bus name")?;

    info!("D-Bus service registered at /org/opdbus/v1/plugins/ovsdb");
    info!("Daemon ready - press Ctrl+C to stop");

    // Keep the connection alive
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

//! D-Bus Service Implementation for OpenVSwitch
//!
//! Implements the org.opdbus.v1.Ovsdb.JsonRpc and org.opdbus.v1.Ovsdb.OpenFlow
//! interfaces as defined in the plugin schema.

use crate::DaemonState;
use anyhow::{Context, Result};
use rovs_ovsdb::Transaction;
use rovs_types::{Atom, Datum};
use serde_json::Value;
use simd_json;
use std::collections::HashMap;
use tracing::{debug, info, warn};
use zbus::interface;

/// D-Bus service for OVSDB operations
pub struct OvsdbDBusService {
    state: DaemonState,
}

impl OvsdbDBusService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

/// Convert a JSON Value to rovs_types::Datum for OVSDB encoding
fn json_to_datum(value: &Value) -> Datum {
    match value {
        Value::Null => Datum::Atom(Atom::Null),
        Value::Bool(b) => Datum::Atom(Atom::Boolean(*b)),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Datum::Atom(Atom::Integer(i))
            } else if let Some(f) = n.as_f64() {
                Datum::Atom(Atom::Real(f))
            } else {
                Datum::Atom(Atom::Null)
            }
        }
        Value::String(s) => Datum::Atom(Atom::String(s.clone())),
        Value::Array(arr) => {
            let data: Vec<Datum> = arr.iter().map(json_to_datum).collect();
            Datum::Vector(data)
        }
        Value::Object(obj) => {
            let mut map: HashMap<String, Datum> = HashMap::new();
            for (k, v) in obj.iter() {
                map.insert(k.clone(), json_to_datum(v));
            }
            Datum::Record(map)
        }
    }
}

/// Convert rovs_types::Datum to JSON Value
fn datum_to_json(datum: &Datum) -> Value {
    match datum {
        Datum::Atom(Atom::Null) => Value::Null,
        Datum::Atom(Atom::Boolean(b)) => Value::Bool(*b),
        Datum::Atom(Atom::Integer(i)) => Value::Number((*i).into()),
        Datum::Atom(Atom::Natural(n)) => Value::Number((*n).into()),
        Datum::Atom(Atom::Real(f)) => {
            serde_json::Number::from_f64(*f)
                .map(Value::Number)
                .unwrap_or(Value::Null)
        }
        Datum::Atom(Atom::String(s)) => Value::String(s.clone()),
        Datum::Atom(Atom::Uuid(u)) => Value::String(u.to_string()),
        Datum::Vector(v) => {
            Value::Array(v.iter().map(datum_to_json).collect())
        }
        Datum::Record(r) => {
            let obj: serde_json::Map<String, Value> = r
                .iter()
                .map(|(k, v)| (k.clone(), datum_to_json(v)))
                .collect();
            Value::Object(obj)
        }
    }
}

#[interface(name = "org.opdbus.v1.Ovsdb.JsonRpc")]
impl OvsdbDBusService {
    /// Execute an OVSDB transaction via JSON-RPC
    ///
    /// Takes a JSON-encoded transaction request and returns the JSON-encoded
    /// response from OVSDB. This is the primary method for OVSDB operations.
    ///
    /// # Arguments
    /// * `request_json` - JSON string containing the OVSDB operation
    ///
    /// # Returns
    /// JSON string with the operation result or error
    async fn transact(&self, request_json: String) -> String {
        debug!("Received transact request: {}", request_json);

        // Parse the request JSON
        let mut bytes = request_json.into_bytes();
        let request: Value = match simd_json::from_slice(&mut bytes) {
            Ok(v) => v,
            Err(e) => {
                warn!("Failed to parse request JSON: {}", e);
                return format!("{{\"error\":\"Invalid JSON: {}\"}}", e);
            }
        };

        // Get OVSDB client
        let mut client_guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => {
                warn!("OVSDB connection failed: {}", e);
                return format!("{{\"error\":\"OVSDB connection failed: {}\"}}", e);
            }
        };

        let client = match client_guard.as_mut() {
            Some(c) => c,
            None => {
                return r#"{"error":"OVSDB client not available"}"#.to_string();
            }
        };

        // Extract operation from request
        let operation = request.get("operation")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown");

        let result = match operation {
            "insert" => {
                // Build insert transaction
                let table = request.get("table")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                let row = request.get("row").cloned().unwrap_or(Value::Null);

                let mut txn = Transaction::new("Open_vSwitch");
                txn.insert(table, json_to_datum(&row));

                match client.transact(&txn).await {
                    Ok(result) => datum_to_json(&result),
                    Err(e) => {
                        json!({"error": format!("Insert failed: {}", e)})
                    }
                }
            }
            "update" => {
                // Build update transaction
                let table = request.get("table")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                let where_clause = request.get("where").cloned().unwrap_or(Value::Null);
                let row = request.get("row").cloned().unwrap_or(Value::Null);

                // For now, return a placeholder - full update requires more complex logic
                json!({
                    "result": format!("Update on {} would be executed", table),
                    "note": "Full update with where clause requires additional implementation"
                })
            }
            "select" => {
                // For select, we read from the IDL
                let table = request.get("table")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let idl = client.idl();
                let rows: Vec<Value> = idl.rows(table)
                    .map(|row| {
                        let mut obj = serde_json::Map::new();
                        // Iterate through columns in the row
                        // This is a simplified version - full implementation would
                        // enumerate all columns from the schema
                        obj.insert("uuid".to_string(), Value::String(row.uuid.to_string()));
                        Value::Object(obj)
                    })
                    .collect();

                json!({
                    "table": table,
                    "rows": rows,
                    "count": rows.len()
                })
            }
            "delete" => {
                let table = request.get("table")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                let uuid_str = request.get("uuid")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let mut txn = Transaction::new("Open_vSwitch");
                txn.delete(table, uuid_str);

                match client.transact(&txn).await {
                    Ok(result) => datum_to_json(&result),
                    Err(e) => {
                        json!({"error": format!("Delete failed: {}", e)})
                    }
                }
            }
            "list_dbs" => {
                match client.list_dbs().await {
                    Ok(dbs) => json!({ "databases": dbs }),
                    Err(e) => json!({"error": format!("List databases failed: {}", e)}),
                }
            }
            _ => {
                json!({"error": format!("Unknown operation: {}", operation)})
            }
        };

        // Serialize result to JSON
        match simd_json::to_string(&result) {
            Ok(s) => s,
            Err(e) => format!("{{\"error\":\"Serialization failed: {}\"}}", e),
        }
    }

    /// Get the daemon status
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();

        let status = json!({
            "connected": connected,
            "socket_path": self.state.socket_path,
            "version": env!("CARGO_PKG_VERSION"),
        });

        status.to_string()
    }
}

// Helper macro for json! macro
#[macro_export]
macro_rules! json {
    ($($json:tt)+) => {
        simd_json::json!($($json)+)
    };
}

use crate::json;

//! OVSDB Proxy - Bridges rovs-jsonrpc to D-Bus
//!
//! Provides structured operations for common OVSDB tasks like
//! bridge management, port operations, and database queries.
//!
//! This module encapsulates the rovs_ovsdb::Client operations
//! behind a clean Rust API that the D-Bus interface uses.

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, Transaction};
use serde_json::Value;
use std::collections::HashMap;
use tracing::{debug, info, warn};

/// Bridge configuration structure
#[derive(Debug, Clone)]
pub struct BridgeConfig {
    pub name: String,
    pub datapath_id: Option<String>,
    pub protocols: Vec<String>,
    pub stp_enable: bool,
    pub rstp_enable: bool,
    pub fail_mode: Option<String>,
    pub external_ids: HashMap<String, String>,
    pub other_config: HashMap<String, String>,
}

impl Default for BridgeConfig {
    fn default() -> Self {
        Self {
            name: String::new(),
            datapath_id: None,
            protocols: vec![],
            stp_enable: false,
            rstp_enable: false,
            fail_mode: None,
            external_ids: HashMap::new(),
            other_config: HashMap::new(),
        }
    }
}

/// Port configuration structure
#[derive(Debug, Clone)]
pub struct PortConfig {
    pub name: String,
    pub bridge: String,
    pub tag: Option<u16>,
    pub trunks: Vec<u16>,
    pub vlan_mode: Option<String>,
    pub bond_mode: Option<String>,
    pub bond_updelay: u32,
    pub bond_downdelay: u32,
    pub external_ids: HashMap<String, String>,
}

impl Default for PortConfig {
    fn default() -> Self {
        Self {
            name: String::new(),
            bridge: String::new(),
            tag: None,
            trunks: vec![],
            vlan_mode: None,
            bond_mode: None,
            bond_updelay: 0,
            bond_downdelay: 0,
            external_ids: HashMap::new(),
        }
    }
}

/// OVSDB Proxy for structured operations
pub struct OvsdbProxy {
    client: Client,
}

impl OvsdbProxy {
    /// Create a new OVSDB proxy from an existing client
    pub fn new(client: Client) -> Self {
        Self { client }
    }

    /// List all bridges in the database
    pub async fn list_bridges(&self) -> Result<Vec<String>> {
        let idl = self.client.idl();
        let bridges: Vec<String> = idl
            .rows("Bridge")
            .filter_map(|row| row.get_string("name"))
            .map(String::from)
            .collect();

        Ok(bridges)
    }

    /// Get detailed information about a bridge
    pub async fn get_bridge_info(&self, name: &str) -> Result<Option<BridgeConfig>> {
        let idl = self.client.idl();

        let bridge_row = idl
            .rows("Bridge")
            .find(|r| r.get_string("name") == Some(name));

        match bridge_row {
            Some(row) => {
                let config = BridgeConfig {
                    name: name.to_string(),
                    datapath_id: row.get_string("datapath_id").map(String::from),
                    protocols: row.get::<Vec<String>>("protocols")
                        .unwrap_or_default(),
                    stp_enable: row.get::<bool>("stp_enable").unwrap_or(false),
                    rstp_enable: row.get::<bool>("rstp_enable").unwrap_or(false),
                    fail_mode: row.get_string("fail_mode").map(String::from),
                    external_ids: row.get::<HashMap<String, String>>("external_ids")
                        .unwrap_or_default(),
                    other_config: row.get::<HashMap<String, String>>("other_config")
                        .unwrap_or_default(),
                };

                Ok(Some(config))
            }
            None => Ok(None),
        }
    }

    /// Create a new bridge
    pub async fn create_bridge(&mut self, name: &str) -> Result<String> {
        if self.bridge_exists(name).await? {
            return Err(anyhow::anyhow!("Bridge '{}' already exists", name));
        }

        let mut txn = Transaction::new("Open_vSwitch");
        txn.create_bridge(name);

        let result = self.client.transact(&txn).await
            .context("Failed to create bridge transaction")?;

        info!("Created bridge: {}", name);
        Ok(format!("Created bridge: {}", name))
    }

    /// Delete a bridge
    pub async fn delete_bridge(&mut self, name: &str) -> Result<String> {
        if !self.bridge_exists(name).await? {
            return Err(anyhow::anyhow!("Bridge '{}' does not exist", name));
        }

        // Get the bridge UUID
        let idl = self.client.idl();
        let bridge_row = idl
            .rows("Bridge")
            .find(|r| r.get_string("name") == Some(name));

        if let Some(row) = bridge_row {
            let uuid = row.uuid;

            let mut txn = Transaction::new("Open_vSwitch");
            txn.delete("Bridge", &uuid.to_string());

            self.client.transact(&txn).await
                .context("Failed to delete bridge transaction")?;

            info!("Deleted bridge: {}", name);
            Ok(format!("Deleted bridge: {}", name))
        } else {
            Err(anyhow::anyhow!("Bridge '{}' not found in IDL", name))
        }
    }

    /// Check if a bridge exists
    pub async fn bridge_exists(&self, name: &str) -> Result<bool> {
        let bridges = self.list_bridges().await?;
        Ok(bridges.contains(&name.to_string()))
    }

    /// Add a port to a bridge
    pub async fn add_port(&mut self, bridge_name: &str, port_name: &str) -> Result<String> {
        if !self.bridge_exists(bridge_name).await? {
            return Err(anyhow::anyhow!("Bridge '{}' does not exist", bridge_name));
        }

        let mut txn = Transaction::new("Open_vSwitch");
        txn.add_port(bridge_name, port_name, "system");

        self.client.transact(&txn).await
            .context("Failed to add port transaction")?;

        info!("Added port {} to bridge {}", port_name, bridge_name);
        Ok(format!("Added port {} to bridge {}", port_name, bridge_name))
    }

    /// Remove a port from a bridge
    pub async fn remove_port(&mut self, port_name: &str) -> Result<String> {
        // Find the port UUID
        let idl = self.client.idl();
        let port_row = idl
            .rows("Port")
            .find(|r| r.get_string("name") == Some(port_name));

        if let Some(row) = port_row {
            let uuid = row.uuid;

            let mut txn = Transaction::new("Open_vSwitch");
            txn.delete("Port", &uuid.to_string());

            self.client.transact(&txn).await
                .context("Failed to remove port transaction")?;

            info!("Removed port: {}", port_name);
            Ok(format!("Removed port: {}", port_name))
        } else {
            Err(anyhow::anyhow!("Port '{}' not found", port_name))
        }
    }

    /// List ports on a bridge
    pub async fn list_bridge_ports(&self, bridge_name: &str) -> Result<Vec<String>> {
        let idl = self.client.idl();

        // Find the bridge row
        let bridge_row = idl
            .rows("Bridge")
            .find(|r| r.get_string("name") == Some(bridge_name));

        match bridge_row {
            Some(row) => {
                // Get the ports column (set of UUID references)
                if let Some(ports_val) = row.get("ports") {
                    let port_uuids = extract_uuids_from_set(ports_val);

                    // Resolve UUIDs to port names
                    let mut port_names = Vec::new();
                    for uuid in port_uuids {
                        if let Some(port_row) = idl.row("Port", &uuid) {
                            if let Some(name) = port_row.get_string("name") {
                                port_names.push(name.to_string());
                            }
                        }
                    }

                    Ok(port_names)
                } else {
                    Ok(vec![])
                }
            }
            None => Err(anyhow::anyhow!("Bridge '{}' not found", bridge_name)),
        }
    }

    /// Get the Open_vSwitch database schema version
    pub async fn get_schema_version(&self) -> Result<String> {
        // This would require a direct JSON-RPC call
        // For now, return a placeholder
        Ok("Open_vSwitch 3.x".to_string())
    }

    /// Execute a raw transaction (for advanced use cases)
    pub async fn raw_transact(&mut self, txn: Transaction) -> Result<Value> {
        let result = self.client.transact(&txn).await
            .context("Transaction failed")?;

        // Convert result to JSON
        Ok(datum_to_json(&result))
    }
}

/// Extract UUIDs from an OVSDB set value
fn extract_uuids_from_set(value: &rovs_types::Datum) -> Vec<uuid::Uuid> {
    match value {
        rovs_types::Datum::Vector(vec) => {
            vec.iter()
                .filter_map(|item| {
                    if let rovs_types::Datum::Atom(rovs_types::Atom::Uuid(u)) = item {
                        Some(*u)
                    } else {
                        None
                    }
                })
                .collect()
        }
        _ => vec![],
    }
}

/// Convert rovs_types::Datum to serde_json::Value
fn datum_to_json(datum: &rovs_types::Datum) -> Value {
    use rovs_types::{Atom, Datum};

    match datum {
        Datum::Atom(Atom::Null) => Value::Null,
        Datum::Atom(Atom::Boolean(b)) => Value::Bool(*b),
        Datum::Atom(Atom::Integer(i)) => Value::Number((*i).into()),
        Datum::Atom(Atom::Natural(n)) => Value::Number((*n).into()),
        Datum::Atom(Atom::Real(f)) => {
            serde_json::Number::from_f64(*f)
                .map(Value::Number)
                .unwrap_or(Value::Null)
        }
        Datum::Atom(Atom::String(s)) => Value::String(s.clone()),
        Datum::Atom(Atom::Uuid(u)) => Value::String(u.to_string()),
        Datum::Vector(v) => {
            Value::Array(v.iter().map(datum_to_json).collect())
        }
        Datum::Record(r) => {
            let obj: serde_json::Map<String, Value> = r
                .iter()
                .map(|(k, v)| (k.clone(), datum_to_json(v)))
                .collect();
            Value::Object(obj)
        }
    }
}

//! OpenFlow Proxy - Passive Controller Absorption via rovs-openflow
//!
//! Implements the org.opdbus.v1.Ovsdb.OpenFlow interface for absorbing
//! OpenFlow connections from OVS bridges in passive controller mode.
//!
//! This allows the daemon to act as a controller for OVS bridges,
//! receiving OpenFlow messages and responding to them programmatically.

use anyhow::{Context, Result};
use rovs_openflow::VConn;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio::sync::{broadcast, Mutex};
use tracing::{debug, error, info, warn};

/// OpenFlow message types for D-Bus signaling
#[derive(Debug, Clone)]
pub enum OpenFlowMessage {
    Hello { version: u8 },
    FeaturesRequest,
    FeaturesReply { datapath_id: u64, n_buffers: u32, n_tables: u8 },
    PacketIn { buffer_id: u32, in_port: u16, data: Vec<u8> },
    FlowMod { match_fields: HashMap<String, String>, actions: Vec<String> },
    PortStatus { port_no: u16, name: String, state: String },
    EchoRequest,
    EchoReply,
    Error { code: u16, data: Vec<u8> },
}

/// Controller configuration
#[derive(Debug, Clone)]
pub struct ControllerConfig {
    /// Listen address for passive controller connections
    pub listen_addr: String,
    /// Default OpenFlow version to negotiate
    pub of_version: u8,
    /// Maximum number of concurrent switch connections
    pub max_connections: usize,
}

impl Default for ControllerConfig {
    fn default() -> Self {
        Self {
            listen_addr: "0.0.0.0:6653".to_string(),
            of_version: 0x04, // OpenFlow 1.3
            max_connections: 16,
        }
    }
}

/// State of a single switch connection
#[derive(Debug)]
struct SwitchConnection {
    /// Connection handle
    conn: Option<VConn>,
    /// Datapath ID from features reply
    datapath_id: Option<u64>,
    /// Connected bridge name
    bridge_name: String,
    /// Connection timestamp
    connected_at: chrono::DateTime<chrono::Utc>,
}

/// OpenFlow Controller Proxy
///
/// Manages passive OpenFlow connections from OVS bridges.
/// Runs a TCP server that accepts connections from switches configured
/// with controller-mode=passive.
pub struct OpenFlowProxy {
    config: ControllerConfig,
    /// Active switch connections
    switches: Arc<Mutex<HashMap<u64, SwitchConnection>>>,
    /// Broadcast channel for OpenFlow events
    event_tx: broadcast::Sender<OpenFlowMessage>,
}

impl OpenFlowProxy {
    /// Create a new OpenFlow proxy
    pub fn new(config: ControllerConfig) -> Self {
        let (event_tx, _) = broadcast::channel(256);

        Self {
            config,
            switches: Arc::new(Mutex::new(HashMap::new())),
            event_tx,
        }
    }

    /// Start the passive controller server
    pub async fn start(&self) -> Result<()> {
        let listener = TcpListener::bind(&self.config.listen_addr)
            .await
            .context("Failed to bind OpenFlow controller socket")?;

        info!(
            "OpenFlow controller listening on {} (OF version {:02x})",
            self.config.listen_addr, self.config.of_version
        );

        let switches = Arc::clone(&self.switches);
        let event_tx = self.event_tx.clone();
        let max_connections = self.config.max_connections;

        loop {
            match listener.accept().await {
                Ok((stream, addr)) => {
                    let switches = Arc::clone(&switches);
                    let event_tx = event_tx.clone();

                    // Check connection limit
                    let current_count = switches.lock().await.len();
                    if current_count >= max_connections {
                        warn!(
                            "Max connections ({}) reached, rejecting connection from {}",
                            max_connections, addr
                        );
                        continue;
                    }

                    info!("New OpenFlow connection from {}", addr);

                    // Spawn handler for this connection
                    tokio::spawn(async move {
                        if let Err(e) = handle_switch_connection(
                            stream,
                            addr.to_string(),
                            switches,
                            event_tx,
                        )
                        .await
                        {
                            warn!("Switch connection handler error: {}", e);
                        }
                    });
                }
                Err(e) => {
                    error!("Failed to accept OpenFlow connection: {}", e);
                }
            }
        }
    }

    /// Subscribe to OpenFlow events
    pub fn subscribe(&self) -> broadcast::Receiver<OpenFlowMessage> {
        self.event_tx.subscribe()
    }

    /// Get list of connected switches
    pub async fn list_switches(&self) -> Vec<(u64, String)> {
        let switches = self.switches.lock().await;
        switches
            .iter()
            .map(|(dpid, conn)| (*dpid, conn.bridge_name.clone()))
            .collect()
    }

    /// Get switch details by datapath ID
    pub async fn get_switch(&self, datapath_id: u64) -> Option<SwitchInfo> {
        let switches = self.switches.lock().await;
        switches.get(&datapath_id).map(|conn| SwitchInfo {
            datapath_id,
            bridge_name: conn.bridge_name.clone(),
            connected_at: conn.connected_at,
        })
    }
}

/// Information about a connected switch
#[derive(Debug, Clone)]
pub struct SwitchInfo {
