/// D-Bus service for OVSDB operations
pub struct OvsdbDBusService {
    state: DaemonState,
}

impl OvsdbDBusService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

/// Convert a JSON string to rovs_types::Datum for OVSDB encoding
fn json_to_datum(value: &simd_json::OwnedValue) -> Datum {
    match value {
        simd_json::OwnedValue::Null => Datum::Atom(Atom::Null),
        simd_json::OwnedValue::Bool(b) => Datum::Atom(Atom::Boolean(*b)),
        simd_json::OwnedValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                Datum::Atom(Atom::Integer(i))
            } else if let Some(f) = n.as_f64() {
                Datum::Atom(Atom::Real(f))
            } else {
                Datum::Atom(Atom::Null)
            }
        }
        simd_json::OwnedValue::String(s) => Datum::Atom(Atom::String(s.clone())),
        simd_json::OwnedValue::Array(arr) => {
            let data: Vec<Datum> = arr.iter().map(json_to_datum).collect();
            Datum::Vector(data)
        }
        simd_json::OwnedValue::Object(obj) => {
            let mut map: HashMap<String, Datum> = HashMap::new();
            for (k, v) in obj.iter() {
                map.insert(k.clone(), json_to_datum(v));
            }
            Datum::Record(map)
        }
        _ => Datum::Atom(Atom::Null),
    }
}

/// Convert rovs_types::Datum to JSON string
fn datum_to_json_string(datum: &Datum) -> String {
    match datum {
        Datum::Atom(Atom::Null) => "null".to_string(),
        Datum::Atom(Atom::Boolean(b)) => b.to_string(),
        Datum::Atom(Atom::Integer(i)) => i.to_string(),
        Datum::Atom(Atom::Natural(n)) => n.to_string(),
        Datum::Atom(Atom::Real(f)) => f.to_string(),
        Datum::Atom(Atom::String(s)) => format!("\"{}\"", s.replace('"', "\\\"")),
        Datum::Atom(Atom::Uuid(u)) => format!("\"{}\"", u),
        Datum::Vector(v) => {
            let items: Vec<String> = v.iter().map(datum_to_json_string).collect();
            format!("[{}]", items.join(","))
        }
        Datum::Record(r) => {
            let items: Vec<String> = r
                .iter()
                .map(|(k, v)| format!("\"{}\":{}", k, datum_to_json_string(v)))
                .collect();
            format!("{{{}}}", items.join(","))
        }
    }
}

