                format!("{{\"result\":\"Update on {} would be executed\",\"note\":\"Full update with where clause requires additional implementation\"}}", table)
            }
            "select" => {
                // For select, we read from the IDL
                let table = request.get("table")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let idl = client.idl();
                let rows: Vec<String> = idl.rows(table)
                    .map(|row| {
                        format!("{{\"uuid\":\"{}\"}}", row.uuid)
                    })
                    .collect();

                format!("{{\"table\":\"{}\",\"rows\":[{}],\"count\":{}}}", 
                    table, rows.join(","), rows.len())
            }
            "delete" => {
                let table = request.get("table")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                let uuid_str = request.get("uuid")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let mut txn = Transaction::new("Open_vSwitch");
                txn.delete(table, uuid_str);

                match client.transact(&txn).await {
                    Ok(result) => datum_to_json_string(&result),
                    Err(e) => {
                        format!("{{\"error\":\"Delete failed: {}\"}}", e)
                    }
                }
            }
            "list_dbs" => {
                match client.list_dbs().await {
                    Ok(dbs) => {
                        let db_list: Vec<String> = dbs.iter()
                            .map(|d| format!("\"{}\"", d))
                            .collect();
                        format!("{{\"databases\":[{}]}}", db_list.join(","))
                    }
                    Err(e) => format!("{{\"error\":\"List databases failed: {}\"}}", e),
                }
            }
            _ => {
                format!("{{\"error\":\"Unknown operation: {}\"}}", operation)
            }
        };

        result
    }

    /// Get the daemon status
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();

        format!("{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
            connected,
            self.state.socket_path,
            env!("CARGO_PKG_VERSION")
        )
    }
}

