//! D-Bus Service Implementation for OpenVSwitch
//!
//! Implements the org.opdbus.v1.Ovsdb.JsonRpc and org.opdbus.v1.Ovsdb.OpenFlow
//! interfaces as defined in the plugin schema.

use crate::DaemonState;
use anyhow::{Context, Result};
use tracing::{debug, info, warn};
use zbus::interface;

/// D-Bus service for OVSDB operations
pub struct OvsdbDBusService {
    state: DaemonState,
}

impl OvsdbDBusService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "org.opdbus.v1.Ovsdb.JsonRpc")]
impl OvsdbDBusService {
    /// Execute an OVSDB transaction via JSON-RPC
    ///
    /// Takes a JSON-encoded transaction request and returns the JSON-encoded
    /// response from OVSDB. This is the primary method for OVSDB operations.
    ///
    /// # Arguments
    /// * `request_json` - JSON string containing the OVSDB operation
    ///
    /// # Returns
    /// JSON string with the operation result or error
    async fn transact(&self, request_json: String) -> String {
        debug!("Received transact request: {}", request_json);

        // Parse the request JSON
        let mut bytes = request_json.into_bytes();
        let request: simd_json::OwnedValue = match simd_json::from_slice(&mut bytes) {
            Ok(v) => v,
            Err(e) => {
                warn!("Failed to parse request JSON: {}", e);
                return format!("{{\"error\":\"Invalid JSON: {}\"}}", e);
            }
        };

        // Get OVSDB client
        let mut client_guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => {
                warn!("OVSDB connection failed: {}", e);
                return format!("{{\"error\":\"OVSDB connection failed: {}\"}}", e);
            }
        };

        let client = match client_guard.as_mut() {
            Some(c) => c,
            None => {
                return r#"{"error":"OVSDB client not available"}"#.to_string();
            }
        };

        // Extract operation from request
        let operation = request.get("operation")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown");

        let result = match operation {
            "create_bridge" => {
                let bridge_name = request.get("name")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let mut txn = rovs_ovsdb::Transaction::new("Open_vSwitch");
                txn.create_bridge(bridge_name);

                match client.transact(&txn).await {
                    Ok(_) => format!("{{\"result\":\"Bridge '{}' created successfully\"}}", bridge_name),
                    Err(e) => format!("{{\"error\":\"Bridge creation failed: {}\"}}", e),
                }
            }
            "delete_bridge" => {
                let bridge_name = request.get("name")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                // Look up bridge UUID from IDL
                let idl = client.idl();
                let bridge_row = idl.rows("Bridge")
                    .find(|r| r.get_string("name") == Some(bridge_name));

                match bridge_row {
                    Some(row) => {
                        let bridge_uuid = row.uuid;

                        // Collect port UUIDs
                        let mut port_uuids: Vec<uuid::Uuid> = Vec::new();
                        if let Some(ports_val) = row.get("ports") {
                            collect_uuid_set(ports_val, &mut port_uuids);
                        }

                        // Collect interface UUIDs
                        let mut iface_uuids: Vec<uuid::Uuid> = Vec::new();
                        for port_uuid in &port_uuids {
                            if let Some(port_row) = idl.row("Port", port_uuid) {
                                if let Some(ifaces_val) = port_row.get("interfaces") {
                                    collect_uuid_set(ifaces_val, &mut iface_uuids);
                                }
                            }
                        }

                        // Build and execute delete transaction
                        let mut txn = rovs_ovsdb::Transaction::new("Open_vSwitch");
                        txn.delete_bridge_uuid(bridge_uuid, &port_uuids, &iface_uuids);

                        match client.transact(&txn).await {
                            Ok(_) => format!("{{\"result\":\"Bridge '{}' deleted successfully\"}}", bridge_name),
                            Err(e) => format!("{{\"error\":\"Bridge deletion failed: {}\"}}", e),
                        }
                    }
                    None => format!("{{\"error\":\"Bridge '{}' not found\"}}", bridge_name),
                }
            }
            "add_port" => {
                let bridge_name = request.get("bridge")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                let port_name = request.get("port")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let mut txn = rovs_ovsdb::Transaction::new("Open_vSwitch");
                txn.add_port(bridge_name, port_name, "system");

                match client.transact(&txn).await {
                    Ok(_) => format!("{{\"result\":\"Port '{}' added to bridge '{}'\"}}", port_name, bridge_name),
                    Err(e) => format!("{{\"error\":\"Add port failed: {}\"}}", e),
                }
            }
            "list_bridges" => {
                let idl = client.idl();
                let bridges: Vec<String> = idl
                    .rows("Bridge")
                    .filter_map(|r| r.get_string("name"))
                    .map(String::from)
                    .collect();

                let bridge_list = bridges.iter()
                    .map(|b| format!("\"{}\"", b))
                    .collect::<Vec<_>>()
                    .join(",");

                format!("{{\"bridges\":[{}],\"count\":{}}}", bridge_list, bridges.len())
            }
            "list_ports" => {
                let bridge_name = request.get("bridge")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let idl = client.idl();

                match idl.rows("Bridge").find(|r| r.get_string("name") == Some(bridge_name)) {
                    Some(row) => {
                        if let Some(ports_val) = row.get("ports") {
                            let port_uuids = collect_uuid_set(ports_val);

                            let port_names: Vec<String> = port_uuids.iter()
                                .filter_map(|uuid| {
                                    idl.row("Port", uuid)
                                        .and_then(|p| p.get_string("name"))
                                        .map(String::from)
                                })
                                .collect();

                            let port_list = port_names.iter()
                                .map(|p| format!("\"{}\"", p))
                                .collect::<Vec<_>>()
                                .join(",");

                            format!("{{\"bridge\":\"{}\",\"ports\":[{}],\"count\":{}}}", 
                                bridge_name, port_list, port_names.len())
                        } else {
                            format!("{{\"bridge\":\"{}\",\"ports\":[],\"count\":0}}", bridge_name)
                        }
                    }
                    None => format!("{{\"error\":\"Bridge '{}' not found\"}}", bridge_name),
                }
            }
            "list_dbs" => {
                match client.list_dbs().await {
                    Ok(dbs) => {
                        let db_list = dbs.iter()
                            .map(|d| format!("\"{}\"", d))
                            .collect::<Vec<_>>()
                            .join(",");
                        format!("{{\"databases\":[{}]}}", db_list)
                    }
                    Err(e) => format!("{{\"error\":\"List databases failed: {}\"}}", e),
                }
            }
            _ => {
                format!("{{\"error\":\"Unknown operation: {}\"}}", operation)
            }
        };

        result
    }

    /// Get the daemon status
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();

        format!("{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
            connected,
            self.state.socket_path,
            env!("CARGO_PKG_VERSION")
        )
    }
}

/// Extract UUIDs from an OVSDB set value
fn collect_uuid_set(value: &rovs_types::Datum) -> Vec<uuid::Uuid> {
    match value {
        rovs_types::Datum::Array(arr) | rovs_types::Datum::Set(arr) => {
            arr.iter()
                .filter_map(|item| {
                    if let rovs_types::Datum::Atom(rovs_types::Atom::Uuid(u)) = item {
                        Some(*u)
                    } else {
                        None
                    }
                })
                .collect()
        }
        _ => vec![],
    }
}

