//! Provides structured operations for common OVSDB tasks like
//! bridge management, port operations, and database queries.
//!
//! This module encapsulates the rovs_ovsdb::Client operations
//! behind a clean Rust API that the D-Bus interface uses.

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, Transaction};
use std::collections::HashMap;
use tracing::{debug, info, warn};

/// Bridge configuration structure
#[derive(Debug, Clone)]
pub struct BridgeConfig {
    pub name: String,
