//! gRPC Service for OpenVSwitch Daemon
//!
//! Provides gRPC endpoints that mirror the D-Bus interface for OVSDB operations.
//! This allows remote clients to interact with OVS over gRPC while the daemon
//! maintains D-Bus as the canonical control plane per AGENTS.md.
//!
//! ## Architecture
//!
//! gRPC calls are translated to D-Bus method calls on the local system bus,
//! ensuring all state changes flow through the D-Bus control plane. The gRPC
//! layer acts as a transport bridge, not a bypass.
//!
//! Services:
//! - OvsdbService: Bridge/port management, database queries
//! - OpenFlowService: Controller management (future)

use anyhow::{Context, Result};
use std::sync::Arc;
use tonic::{Request, Response, Status};
use tracing::{debug, info, warn};
use zbus::connection::Connection;

/// Generated protobuf types
pub mod proto {
    tonic::include_proto!("ovsdaemon.v1");
}

use proto::{
    ovsdb_service_server::{OvsdbService, OvsdbServiceServer},
    BridgeRequest, BridgeResponse, BridgesRequest, BridgesResponse,
    PortRequest, PortResponse, PortsRequest, PortsResponse,
    DatabaseRequest, DatabaseResponse, StatusRequest, StatusResponse,
};

/// D-Bus service proxy for OVSDB operations
///
/// Wraps D-Bus calls to the local OVSDB daemon and translates responses
/// to gRPC protobuf messages.
pub struct OvsdbGrpcService {
    /// D-Bus connection for forwarding calls
    dbus_conn: Arc<Connection>,
}

impl OvsdbGrpcService {
    /// Create a new gRPC service with D-Bus connection
    pub async fn new() -> Result<Self> {
        let dbus_conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus")?;

        info!("OvsdbGrpcService connected to system D-Bus");

        Ok(Self {
            dbus_conn: Arc::new(dbus_conn),
        })
    }

    /// Build the gRPC server with all services
    pub fn into_server(self) -> OvsdbServiceServer<Self> {
        OvsdbServiceServer::new(self)
    }
}

#[tonic::async_trait]
impl OvsdbService for OvsdbGrpcService {
    /// Create a new OVS bridge
    async fn create_bridge(
        &self,
        request: Request<BridgeRequest>,
    ) -> Result<Response<BridgeResponse>, Status> {
        let req = request.into_inner();
        let bridge_name = req.name;

        debug!("gRPC create_bridge: {}", bridge_name);

        // Call D-Bus method
        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        // Build JSON-RPC request for transact
        let json_request = format!(
            r#"{{"operation":"create_bridge","name":"{}"}}"#,
            bridge_name
        );

        let result = proxy
            .transact(json_request)
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        // Parse result to determine success
        let success = !result.contains("error");

        Ok(Response::new(BridgeResponse {
            name: bridge_name,
            success,
            message: result,
        }))
    }

    /// Delete an OVS bridge
    async fn delete_bridge(
        &self,
        request: Request<BridgeRequest>,
    ) -> Result<Response<BridgeResponse>, Status> {
        let req = request.into_inner();
        let bridge_name = req.name;

        debug!("gRPC delete_bridge: {}", bridge_name);

        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        let json_request = format!(
            r#"{{"operation":"delete_bridge","name":"{}"}}"#,
            bridge_name
        );

        let result = proxy
            .transact(json_request)
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        let success = !result.contains("error");

        Ok(Response::new(BridgeResponse {
            name: bridge_name,
            success,
            message: result,
        }))
    }

    /// List all bridges
    async fn list_bridges(
        &self,
        _request: Request<BridgesRequest>,
    ) -> Result<Response<BridgesResponse>, Status> {
        debug!("gRPC list_bridges");

        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        let json_request = r#"{"operation":"list_bridges"}"#.to_string();

        let result = proxy
            .transact(json_request)
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        // Parse JSON result to extract bridge names
        // Result format: {"bridges":["br0","br1"],"count":2}
        let bridges: Vec<String> = parse_bridge_list(&result)?;

        Ok(Response::new(BridgesResponse {
            bridges,
            count: 0, // Will be filled from parsed result
        }))
    }

    /// Add a port to a bridge
    async fn add_port(
        &self,
        request: Request<PortRequest>,
    ) -> Result<Response<PortResponse>, Status> {
        let req = request.into_inner();
        let bridge_name = req.bridge;
        let port_name = req.name;

        debug!("gRPC add_port: {} to bridge {}", port_name, bridge_name);

        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        let json_request = format!(
            r#"{{"operation":"add_port","bridge":"{}","port":"{}"}}"#,
            bridge_name, port_name
        );

        let result = proxy
            .transact(json_request)
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        let success = !result.contains("error");

        Ok(Response::new(PortResponse {
            name: port_name,
            bridge: bridge_name,
            success,
            message: result,
        }))
    }

    /// List ports on a bridge
    async fn list_ports(
        &self,
        request: Request<PortsRequest>,
    ) -> Result<Response<PortsResponse>, Status> {
        let req = request.into_inner();
        let bridge_name = req.bridge;

        debug!("gRPC list_ports for bridge: {}", bridge_name);

        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        let json_request = format!(
            r#"{{"operation":"list_ports","bridge":"{}"}}"#,
            bridge_name
        );

        let result = proxy
            .transact(json_request)
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        // Parse ports from result
        let ports: Vec<String> = parse_port_list(&result)?;

        Ok(Response::new(PortsResponse {
            bridge: bridge_name,
            ports,
            count: 0,
        }))
    }

    /// List OVS databases
    async fn list_databases(
        &self,
        _request: Request<DatabaseRequest>,
    ) -> Result<Response<DatabaseResponse>, Status> {
        debug!("gRPC list_databases");

        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        let json_request = r#"{"operation":"list_dbs"}"#.to_string();

        let result = proxy
            .transact(json_request)
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        // Parse database list from result
        let databases: Vec<String> = parse_database_list(&result)?;

        Ok(Response::new(DatabaseResponse {
            databases,
            count: databases.len() as i32,
        }))
    }

    /// Get daemon status
    async fn get_status(
        &self,
        _request: Request<StatusRequest>,
    ) -> Result<Response<StatusResponse>, Status> {
        debug!("gRPC get_status");

        let proxy = self
            .dbus_conn
            .object_server()
            .interface::<_, crate::dbus::OvsdbDBusService>("/org/opdbus/v1/plugins/ovsdb")
            .await
            .map_err(|e| Status::internal(format!("D-Bus proxy error: {}", e)))?;

        let result = proxy
            .status()
            .await
            .map_err(|e| Status::internal(format!("D-Bus call failed: {}", e)))?;

        // Parse status JSON
        let (connected, version) = parse_status(&result)?;

        Ok(Response::new(StatusResponse {
            connected,
            version,
            message: result,
        }))
    }
}

/// Parse bridge list from JSON response
fn parse_bridge_list(json: &str) -> Result<Vec<String>, Status> {
    // Simple parsing - in production use simd_json or serde
    // Expected: {"bridges":["br0","br1"],"count":2}
    if let Some(start) = json.find("[") {
        if let Some(end) = json.find("]") {
            let array_str = &json[start + 1..end];
            let bridges: Vec<String> = array_str
                .split(',')
                .map(|s| s.trim().trim_matches('"').to_string())
                .filter(|s| !s.is_empty())
                .collect();
            return Ok(bridges);
        }
    }
    Ok(vec![])
}

/// Parse port list from JSON response
fn parse_port_list(json: &str) -> Result<Vec<String>, Status> {
    // Expected: {"bridge":"br0","ports":["p0","p1"],"count":2}
    if let Some(ports_start) = json.find("\"ports\":[") {
        let sub = &json[ports_start + 9..];
        if let Some(end) = sub.find("]") {
            let array_str = &sub[..end];
            let ports: Vec<String> = array_str
                .split(',')
                .map(|s| s.trim().trim_matches('"').to_string())
                .filter(|s| !s.is_empty())
                .collect();
            return Ok(ports);
        }
    }
    Ok(vec![])
}

/// Parse database list from JSON response
fn parse_database_list(json: &str) -> Result<Vec<String>, Status> {
    // Expected: {"databases":["Open_vSwitch"]}
    if let Some(start) = json.find("[") {
        if let Some(end) = json.find("]") {
            let array_str = &json[start + 1..end];
            let dbs: Vec<String> = array_str
                .split(',')
                .map(|s| s.trim().trim_matches('"').to_string())
                .filter(|s| !s.is_empty())
                .collect();
            return Ok(dbs);
        }
    }
    Ok(vec![])
}

/// Parse status response
fn parse_status(json: &str) -> Result<(bool, String), Status> {
    // Expected: {"connected":true,"socket_path":"...","version":"1.0.0"}
    let connected = json.contains("\"connected\":true");

    let version = if let Some(start) = json.find("\"version\":\"") {
        let sub = &json[start + 11..];
        if let Some(end) = sub.find("\"") {
            sub[..end].to_string()
        } else {
            "unknown".to_string()
        }
    } else {
        "unknown".to_string()
    };

    Ok((connected, version))
}

/// Run the gRPC server
pub async fn run_grpc_server(
    addr: std::net::SocketAddr,
) -> Result<()> {
    let service = OvsdbGrpcService::new().await?;
    let server = service.into_server();

    info!("Starting gRPC server on {}", addr);

    tonic::transport::Server::builder()
        .add_service(server)
        .serve(addr)
        .await
        .context("gRPC server error")?;

    Ok(())
}

