//! OpenVSwitch D-Bus Daemon
//!
//! Provides D-Bus interfaces for OVSDB and OpenFlow operations via native
//! rovs primitives. This daemon replaces OvsdbClient CLI wrappers with a
//! schema-driven D-Bus service.
//!
//! D-Bus object path: /org/opdbus/v1/plugins/ovsdb
//!
//! Interfaces:
//! - org.opdbus.v1.Ovsdb.JsonRpc (transact method for OVSDB operations)
//! - org.opdbus.v1.Ovsdb.OpenFlow (passive controller absorption)
//!
//! ## Architecture
//!
//! Per AGENTS.md D-Bus-first rules:
//! - All OVS state changes go through D-Bus methods
//! - rovs-jsonrpc::Connection is used for OVSDB JSON-RPC wire protocol
//! - rovs-openflow::VConn handles OpenFlow controller connections
//! - No subprocess spawning - pure Rust native implementation
//!
//! ## Modes
//! - D-Bus mode (default): Runs as D-Bus service only
//! - gRPC mode: Adds gRPC server that proxies to D-Bus

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, ClientConfig};
use std::path::Path;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{info, warn};
use zbus::connection::Connection;

mod dbus;
mod grpc;
mod openflow_proxy;
mod ovsdb_proxy;

use dbus::OvsdbDBusService;

/// CLI arguments
#[derive(Debug, Clone)]
struct Args {
    /// gRPC listen address (enables gRPC mode)
    grpc_addr: Option<String>,
    /// OVS socket path override
    ovs_socket: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut grpc_addr = None;
        let mut ovs_socket = None;

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--grpc" => {
                    if i + 1 < args.len() {
                        grpc_addr = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                "--ovs-socket" => {
                    if i + 1 < args.len() {
                        ovs_socket = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }

        Self {
            grpc_addr,
            ovs_socket,
        }
    }
}

/// Default OVS socket path
const DEFAULT_OVS_SOCKET: &str = "/var/run/openvswitch/db.sock";

/// Alternative socket paths to try
const OVS_SOCKET_PATHS: &[&str] = &["/run/openvswitch/db.sock", "/var/run/openvswitch/db.sock"];

/// Find the OVS socket path
fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

/// Daemon state holding OVS connections
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB client for database operations
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// Socket path for OVSDB connection
    pub socket_path: String,
}

impl DaemonState {
    fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
        }
    }

    /// Get or create OVSDB client
    async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;

        if guard.is_none() {
            let config = ClientConfig::default().database("Open_vSwitch");

            let addr = format!("unix:{}", self.socket_path);
            let client = Client::connect_with_config(&addr, config)
                .await
                .context("Failed to connect to OVSDB")?;

            info!("Connected to OVSDB at {}", self.socket_path);
            *guard = Some(client);
        }

        Ok(guard)
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon");

    // Parse CLI arguments
    let args = Args::parse();

    // Find OVS socket
    let socket_path = args.ovs_socket.unwrap_or_else(find_ovs_socket);
    info!("Using OVS socket: {}", socket_path);

    // Create daemon state
    let state = DaemonState::new(socket_path);

    // Test connection early
    if let Err(e) = state.get_ovsdb().await {
        warn!(
            "Could not connect to OVSDB: {}. Daemon will retry on first request.",
            e
        );
    }

    // Create D-Bus service
    let service = OvsdbDBusService::new(state);

    // Build D-Bus connection
    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;

    info!("Connected to system D-Bus");

    // Serve the OvsdbDBusService on the connection
    conn.object_server()
        .at("/org/opdbus/v1/plugins/ovsdb", service)
        .await
        .context("Failed to register D-Bus object")?;

    // Request the bus name
    conn.request_name("org.opdbus.v1.plugins.ovsdb")
        .await
        .context("Failed to request bus name")?;

    info!("D-Bus service registered at /org/opdbus/v1/plugins/ovsdb");

    // Optionally start gRPC server
    if let Some(grpc_addr) = args.grpc_addr {
        let addr: std::net::SocketAddr = grpc_addr.parse().context("Invalid gRPC address")?;

        info!("Starting gRPC server on {}", addr);

        // Spawn gRPC server in background task
        tokio::spawn(async move {
            if let Err(e) = grpc::run_grpc_server(addr).await {
                warn!("gRPC server error: {}", e);
            }
        });
    }

    info!("Daemon ready - press Ctrl+C to stop");

    // Keep the connection alive
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

