//! OVSDB Daemon Plugin
//!
//! Represents the op-openvswitch-daemon binary as a state plugin.
//! Per AGENTS.md: "the schema IS the plugin" - this plugin's schema
//! defines the daemon's interface contract.
//!
//! The daemon itself is an external binary that registers on D-Bus at
//! org.opdbus.v1.plugins.ovsdb. This plugin provides the schema definition
//! and state representation for the system registry.

use crate::state_plugins::plugin_schema_defs;
use op_state::{Plugin, PluginCapabilities, PluginState};
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

/// OVSDB Daemon Plugin
///
/// Schema-driven definition of the native OVSDB D-Bus daemon.
/// The daemon binary (op-openvswitch-daemon) implements the actual
/// OVSDB operations; this plugin provides the schema contract.
pub struct OvsdbDaemonPlugin {
    state: PluginState,
}

impl OvsdbDaemonPlugin {
    pub fn new() -> Self {
        Self {
            state: PluginState::default(),
        }
    }

    /// Get the daemon's current status from D-Bus if available
    async fn query_daemon_status(&self) -> Option<Value> {
        // Try to connect to the daemon via D-Bus
        // If running, query its status method
        match zbus::connection::Connection::system().await {
            Ok(conn) => {
                let proxy = conn
                    .object_server()
                    .interface::<
                        _,
                        crate::state_plugins::ovsdb_bridge::OvsBridgeInterface,
                    >("/org/opdbus/v1/plugins/ovsdb")
                    .await;

                // For now, return static info - the daemon's presence
                // is detected by D-Bus name ownership
                Some(simd_json::json!({
                    "daemon_version": env!("CARGO_PKG_VERSION"),
                    "connected": false, // Would query actual daemon
                    "socket_path": "/var/run/openvswitch/db.sock",
                    "bridges": [],
                    "operations_supported": [
                        "create_bridge",
                        "delete_bridge",
                        "add_port",
                        "list_bridges",
                        "list_ports",
                        "list_dbs"
                    ],
                    "dbus_bus_name": "org.opdbus.v1.plugins.ovsdb",
                    "dbus_object_path": "/org/opdbus/v1/plugins/ovsdb",
                }))
            }
            Err(_) => None,
        }
    }
}

impl Default for OvsdbDaemonPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait::async_trait]
impl Plugin for OvsdbDaemonPlugin {
    fn name(&self) -> &str {
        "ovsdb_daemon"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn category(&self) -> &str {
        "network"
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities::STATE_QUERY
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(plugin_schema_defs::ovsdb_daemon_plugin_schema())
    }

    async fn state(&self) -> PluginState {
        self.state.clone()
    }

    async fn query_current_state(&self) -> Result<Value, op_state::StateError> {
        // Return the daemon's status or a default if not running
        let status = self.query_daemon_status().await.unwrap_or_else(|| {
            simd_json::json!({
