//! OVSDB Proxy - Bridges rovs-jsonrpc to D-Bus
//!
//! Provides structured operations for common OVSDB tasks like
//! bridge management, port operations, and database queries.
//!
//! This module encapsulates the rovs_ovsdb::Client operations
//! behind a clean Rust API that the D-Bus interface uses.

#![allow(dead_code)]

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, Transaction};
use std::collections::HashMap;
use tracing::info;

/// Bridge configuration structure
#[derive(Debug, Clone, Default)]
pub struct BridgeConfig {
    pub name: String,
    pub datapath_id: Option<String>,
    pub protocols: Vec<String>,
    pub stp_enable: bool,
    pub rstp_enable: bool,
    pub fail_mode: Option<String>,
    pub external_ids: HashMap<String, String>,
    pub other_config: HashMap<String, String>,
}

/// Port configuration structure
#[derive(Debug, Clone, Default)]
pub struct PortConfig {
    pub name: String,
    pub interfaces: Vec<InterfaceConfig>,
    pub vlan_mode: Option<String>,
    pub tag: Option<u16>,
    pub trunks: Vec<u16>,
    pub external_ids: HashMap<String, String>,
    pub other_config: HashMap<String, String>,
}

/// Interface configuration structure
#[derive(Debug, Clone, Default)]
pub struct InterfaceConfig {
    pub name: String,
    pub iface_type: String,
    pub options: HashMap<String, String>,
    pub external_ids: HashMap<String, String>,
    pub admin_state: Option<String>,
    pub link_state: Option<String>,
    pub mac: Option<String>,
    pub mtu: Option<u32>,
    pub ofport: Option<u32>,
}

#[allow(clippy::derivable_impls)]
impl PortConfig {
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            ..Default::default()
        }
    }
}

/// OVSDB Proxy for structured operations
pub struct OvsdbProxy {
    client: Client,
}

impl OvsdbProxy {
    /// Create a new OVSDB proxy connected to the specified socket
    pub async fn new(socket_path: &str) -> Result<Self> {
        let client = Client::connect(&format!("unix:{}", socket_path))
            .await
            .context("Failed to connect to OVSDB")?;

        Ok(Self { client })
    }

    /// List all bridges
    pub async fn list_bridges(&self) -> Result<Vec<String>> {
        let idl = self.client.idl();
        let mut names = Vec::new();

        for row in idl.rows("Bridge") {
            if let Some(name) = row.get_string("name") {
                names.push(name.to_string());
            }
        }

        Ok(names)
    }

    /// Create a new bridge
    pub async fn create_bridge(&mut self, name: &str) -> Result<String> {
        let mut txn = Transaction::new("Open_vSwitch");

        // Create bridge row
        let bridge_uuid = txn.insert("Bridge");
        txn.set(&bridge_uuid, "name", name);
        txn.set(&bridge_uuid, "stp_enable", false);

        // Add bridge to Open_vSwitch table's bridges column
        let ovs_uuid = self.get_ovs_uuid().await?;
        txn.mutate(&ovs_uuid, "bridges", &[&bridge_uuid]);

        self.client.commit(&mut txn).await.context("Failed to create bridge")?;

        info!("Created bridge: {}", name);
        Ok(format!("Created bridge: {}", name))
    }

    /// Delete a bridge
    pub async fn delete_bridge(&mut self, name: &str) -> Result<String> {
        let idl = self.client.idl();

        // Find the bridge UUID
        let bridge_row = idl.rows("Bridge").find(|r| r.get_string("name") == Some(name));

        if let Some(row) = bridge_row {
            let uuid = row.uuid();

            let mut txn = Transaction::new("Open_vSwitch");

            // Remove bridge from Open_vSwitch table
            let ovs_uuid = self.get_ovs_uuid().await?;
            txn.mutate_delete(&ovs_uuid, "bridges", &[&uuid]);

            // Delete the bridge row
            txn.delete(&uuid);

            self.client.commit(&mut txn).await.context("Failed to delete bridge")?;

            info!("Deleted bridge: {}", name);
            Ok(format!("Deleted bridge: {}", name))
        } else {
            Err(anyhow::anyhow!("Bridge '{}' not found", name))
        }
    }

    /// Get the Open_vSwitch table UUID
    async fn get_ovs_uuid(&self) -> Result<uuid::Uuid> {
        let idl = self.client.idl();

        idl.rows("Open_vSwitch")
            .next()
            .map(|r| r.uuid())
            .ok_or_else(|| anyhow::anyhow!("Open_vSwitch table not found"))
    }

    /// Check if a bridge exists
    pub async fn bridge_exists(&self, name: &str) -> Result<bool> {
        let idl = self.client.idl();
        Ok(idl.rows("Bridge").any(|r| r.get_string("name") == Some(name)))
    }

    /// Add a port to a bridge
    pub async fn add_port(&mut self, bridge_name: &str, port_name: &str) -> Result<String> {
        let idl = self.client.idl();

        // Find the bridge UUID
        let bridge_row = idl
            .rows("Bridge")
            .find(|r| r.get_string("name") == Some(bridge_name));

        if bridge_row.is_none() {
            return Err(anyhow::anyhow!("Bridge '{}' not found", bridge_name));
        }

        let bridge_uuid = bridge_row.unwrap().uuid();

        let mut txn = Transaction::new("Open_vSwitch");

        // Create port row
        let port_uuid = txn.insert("Port");
        txn.set(&port_uuid, "name", port_name);

        // Create interface row
        let iface_uuid = txn.insert("Interface");
        txn.set(&iface_uuid, "name", port_name);
        txn.set(&iface_uuid, "type", "system");

        // Link interface to port
        txn.set(&port_uuid, "interfaces", &[&iface_uuid]);

        // Add port to bridge
        txn.mutate(&bridge_uuid, "ports", &[&port_uuid]);

        self.client.commit(&mut txn).await.context("Failed to add port")?;

        info!("Added port {} to bridge {}", port_name, bridge_name);
        Ok(format!("Added port {} to bridge {}", port_name, bridge_name))
    }

    /// Remove a port
    pub async fn remove_port(&mut self, port_name: &str) -> Result<String> {
        let idl = self.client.idl();

        // Find the port UUID
        let port_row = idl.rows("Port").find(|r| r.get_string("name") == Some(port_name));

        if let Some(row) = port_row {
            let port_uuid = row.uuid();

            // Find all bridges that have this port
            let mut txn = Transaction::new("Open_vSwitch");

            // Remove port from any bridges that reference it
            for bridge_row in idl.rows("Bridge") {
                if let Some(ports_val) = bridge_row.get("ports") {
                    let port_uuids = extract_uuids_from_value(ports_val);
                    if port_uuids.contains(&port_uuid) {
                        txn.mutate_delete(&bridge_row.uuid(), "ports", &[&port_uuid]);
                    }
                }
            }

            // Delete the port row (this will also delete associated interfaces)
            txn.delete(&port_uuid);

            self.client
                .commit(&mut txn)
                .await
                .context("Failed to remove port transaction")?;

            info!("Removed port: {}", port_name);
            Ok(format!("Removed port: {}", port_name))
        } else {
            Err(anyhow::anyhow!("Port '{}' not found", port_name))
        }
    }

    /// List ports on a bridge
    #[allow(dead_code)]
    pub async fn list_bridge_ports(&self, bridge_name: &str) -> Result<Vec<String>> {
        let idl = self.client.idl();

        // Find the bridge row
        let bridge_row = idl
            .rows("Bridge")
            .find(|r| r.get_string("name") == Some(bridge_name));

        match bridge_row {
            Some(row) => {
                // Get the ports column (set of UUID references)
                if let Some(ports_val) = row.get("ports") {
                    let port_uuids = extract_uuids_from_value(ports_val);

                    // Resolve UUIDs to port names
                    let mut port_names = Vec::new();
                    for uuid in port_uuids {
                        if let Some(port_row) = idl.row("Port", &uuid) {
                            if let Some(name) = port_row.get_string("name") {
                                port_names.push(name.to_string());
                            }
                        }
                    }

                    Ok(port_names)
                } else {
                    Ok(vec![])
                }
            }
            None => Err(anyhow::anyhow!("Bridge '{}' not found", bridge_name)),
        }
    }

    /// Get the Open_vSwitch database schema version
    pub async fn get_schema_version(&self) -> Result<String> {
        // This would require a direct JSON-RPC call
        // For now, return a placeholder
        Ok("Open_vSwitch 3.x".to_string())
    }

    /// Execute a raw transaction (for advanced use cases)
    pub async fn raw_transact(&mut self, txn: &mut Transaction) -> Result<bool> {
        self.client.commit(txn).await.context("Transaction failed")
    }
}

